    if(state.view==='signin')return `<div class="container"><div class="form-card"><span class="label">ACCESSO SICURO</span><h1>Bentornato.</h1><p>Accedi con email e password. I clienti possono iscriversi liberamente; ai ristoratori serve un invito.</p><div class="card"><form id="signin-form" class="stack"><div class="field"><label for="gd-signin-email">Email</label><input id="gd-signin-email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="gd-signin-password">Password</label><input id="gd-signin-password" name="password" type="password" autocomplete="current-password" required></div>${captchaSlot('login')}<button class="btn btn-dark btn-block" type="submit">Accedi ${svg('arrow')}</button></form><div class="form-footer">${button('Password dimenticata','forgot','btn-ghost btn-small')}</div></div><div class="form-footer">${button('Crea un account','signup','btn-ghost')}</div></div></div>`;
